fn find_max(nums: Vec<i32>) -> i32 {
    // Since nums is non-empty, we can safely initialize max_val with the first element.
    let mut max_val = nums[0];
    // Iterate over all elements and update max_val whenever we find a larger one.
    for &num in &nums {
        if num > max_val {
            max_val = num;
        }
    }
    max_val
}

